def seed_annual_kyc_cycles(apps, schema_editor):
    Centre = apps.get_model("web", "CentreUserAccount")
    User = apps.get_model("web", "User")
    Status = apps.get_model("web", "CentreAnnualKYCStatus")
    now = timezone.now()

    def add_months(value, months):
        month_index = value.month - 1 + months
        year = value.year + month_index // 12
        month = month_index % 12 + 1
        day = min(value.day, calendar.monthrange(year, month)[1])
        return value.replace(year=year, month=month, day=day)

    for centre in Centre.objects.all().iterator():
        user_date = User.objects.filter(pk=centre.user_id).values_list("date_joined", flat=True).first()
        base = centre.created_at or user_date or now
        Status.objects.get_or_create(
            centre_id=centre.pk,
            defaults={"next_kyc_due_at": add_months(base, 12)},
        )


